// Hashing: repartir 20.000 clientes entre depósitos, con módulo y con anillo.
function hash(s) {                       // FNV-1a de 32 bits + mezcla final para repartir bien los bits
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b); h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35); h ^= h >>> 16;
  return h >>> 0;                        // entero sin signo, de 0 a 2^32 - 1
}
class Anillo {
  constructor(nodos, v, sal) {           // v = puntos (nodos virtuales) por nodo físico
    this.pts = [];
    for (const n of nodos) for (let i = 0; i < v; i++) this.pts.push([hash(`${sal}|${n}#${i}`), n]);
    this.pts.sort((a, b) => a[0] - b[0]);
  }
  dueño(clave) {                         // primer punto con posición >= hash(clave); si no hay, da la vuelta
    const h = hash(clave); let lo = 0, hi = this.pts.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (this.pts[m][0] < h) lo = m + 1; else hi = m; }
    return this.pts[lo % this.pts.length][1];
  }
}
const claves = Array.from({ length: 20000 }, (_, i) => `cliente-${i}`);
const carga = (f) => { const c = {}; for (const k of claves) { const n = f(k); c[n] = (c[n] || 0) + 1; } return c; };
const desbalance = (c) => Math.max(...Object.values(c)) / (claves.length / Object.keys(c).length);

