}

// Quórum R + W > N: probamos TODAS las combinaciones posibles de réplicas, sin azar.
function subconjuntos(n, k) {            // todos los subconjuntos de k réplicas elegidos entre n
  const out = [];
  (function rec(ini, acc) {
    if (acc.length === k) { out.push(acc.slice()); return; }
    for (let i = ini; i < n; i++) { acc.push(i); rec(i + 1, acc); acc.pop(); }
  })(0, []);
  return out;
}
function prueba(N, R, W) {
  let veNuevo = 0, total = 0;
  for (const escr of subconjuntos(N, W)) {          // la escritura (versión 2) solo llega a estas W réplicas
    const versiones = Array(N).fill(1);             // el resto se queda con la versión 1
    for (const i of escr) versiones[i] = 2;
    for (const lect of subconjuntos(N, R)) {        // la lectura le pregunta a R réplicas y se queda con la versión más alta
      total++;
      if (Math.max(...lect.map((i) => versiones[i])) === 2) veNuevo++;
    }
  }
  return [veNuevo, total];
}
const casos = { 3: [[1,1],[2,1],[1,2],[2,2],[3,1],[1,3]], 5: [[1,1],[2,3],[3,3],[1,5]] };
for (const N of [3, 5]) {
  console.log(`N = ${N}`);
  for (const [R, W] of casos[N]) {
    const [a, t] = prueba(N, R, W);
    console.log(`  R=${R} W=${W}  R+W ${R + W > N ? '>' : '<='} N   la lectura ve la versión nueva en ${String(a).padStart(3)} de ${String(t).padStart(3)} combinaciones (${(100 * a / t).toFixed(0)} %)`);
  }
}

// Mini-Dynamo: lista de preferencia [A, B, C] con N = 3 y un nodo extra D que ayuda cuando alguien cae.
const nodos = Object.fromEntries('ABCD'.split('').map((n) => [n, { vivo: true, datos: new Map(), pistas: [] }]));
const lista = ['A', 'B', 'C', 'D'];       // los primeros N = 3 son los dueños; D es el siguiente en el anillo
const N = 3, R = 2, W = 2;
let version = 0;
const estado = (k) => lista.map((n) => `${n}${nodos[n].vivo ? '' : '(caído)'}=${nodos[n].datos.get(k)?.v ?? '-'}`).join(' ');

function put(k, valor) {                  // cuórum «descuidado» (sloppy): usa los primeros N nodos SANOS de la lista
  const sanos = lista.filter((n) => nodos[n].vivo).slice(0, N);
  version++; let acks = 0;
  for (const n of sanos) {
    nodos[n].datos.set(k, { v: version, valor });
    if (!lista.slice(0, N).includes(n)) {  // D guarda la réplica con una pista: «esto es de A»
      const dueño = lista.slice(0, N).find((x) => !nodos[x].vivo);
      nodos[n].pistas.push({ k, para: dueño });
    }
    acks++;
  }
  return acks >= W ? 'ok' : 'rechazada';
}
function get(k, quienes) {                // lectura con R nodos; repara a los atrasados
  const resp = quienes.map((n) => ({ n, d: nodos[n].datos.get(k) }));
  const mejor = resp.reduce((a, b) => ((b.d?.v ?? 0) > (a.d?.v ?? 0) ? b : a));
  for (const r of resp) if ((r.d?.v ?? 0) < mejor.d.v) { nodos[r.n].datos.set(k, mejor.d); console.log(`   reparación: ${r.n} estaba en v${r.d?.v ?? '-'} y pasa a v${mejor.d.v}`); }
  return mejor.d;
}
const traer = () => { // cuando un nodo vuelve, los que guardan pistas para él se las entregan
  for (const n of lista) for (const p of nodos[n].pistas.splice(0)) if (nodos[p.para].vivo) {
    nodos[p.para].datos.set(p.k, nodos[n].datos.get(p.k)); nodos[n].datos.delete(p.k);
    console.log(`   entrega pendiente: ${n} le pasa «${p.k}» a ${p.para} y la borra de su disco`);
  } else nodos[n].pistas.push(p);
};

